import { tool } from "ai"

import { listIssues, resolveSpec } from "./resolve"
import { createFableToolSchema, type ContentBlockType } from "./schema"

export const FABLE_TOOL_NAME = "render_ui"

export interface FableToolOptions {
  /** Restrict the catalog. Fewer blocks: shorter schema, better picks. */
  include?: readonly ContentBlockType[]
  description?: string
}

/**
 * The AI SDK tool the model calls to answer with UI. It has no side effects:
 * execute only acknowledges, so the conversation history stays valid and the
 * client renders the (streamed) input.
 *
 *   streamText({ tools: { render_ui: createFableTool() }, stopWhen: hasToolCall("render_ui") })
 */
export function createFableTool(options: FableToolOptions = {}) {
  return tool({
    description:
      options.description ??
      "Show the answer to the user as rich UI built from blocks (text, tables, charts, media, forms, drafts, actions). The user sees it immediately.",
    inputSchema: createFableToolSchema(options.include),
    // Tells the model which blocks were skipped, so a follow-up turn can fix them.
    execute: async (input) => {
      const skipped = listIssues(resolveSpec(input).items).slice(0, 5)
      return { status: "displayed" as const, blocks: input.blocks.length, ...(skipped.length ? { skipped } : {}) }
    },
  })
}

export const fableTool = createFableTool()

import { FABLE_DOWNLOAD_TYPES } from "./schema"

/**
 * Pure policy functions. Everything the model writes passes through one of
 * these before it can become a link, an image request, or a file.
 */

export type FableDownloadType = (typeof FABLE_DOWNLOAD_TYPES)[number]

export interface FableImagePolicy {
  /**
   * Hostnames whose images load immediately, e.g. ["images.unsplash.com"].
   * A leading "*." matches subdomains. Other https images wait for a click.
   */
  allowedHosts?: string[]
  /** "ask" (default) shows a click-to-load card; "block" never loads them. */
  otherHosts?: "ask" | "block"
}

function parseUrl(value: string): URL | null {
  try {
    return new URL(value.trim())
  } catch {
    return null
  }
}

/** Links: https, http and mailto only; no embedded credentials. */
export function safeLinkUrl(value: string | undefined | null): string | null {
  if (!value) return null
  const url = parseUrl(value)
  if (!url) return null
  if (url.protocol === "mailto:") return url.href
  if (url.protocol !== "https:" && url.protocol !== "http:") return null
  if (url.username || url.password) return null
  return url.href
}

/** Images: https only, no credentials. Returns null when the URL can never load. */
export function safeImageUrl(value: string | undefined | null): URL | null {
  if (!value) return null
  const url = parseUrl(value)
  if (!url || url.protocol !== "https:" || url.username || url.password) return null
  return url
}

export function isHostAllowed(hostname: string, allowedHosts: readonly string[] = []) {
  const host = hostname.toLowerCase()
  return allowedHosts.some((entry) => {
    const rule = entry.toLowerCase().trim()
    if (rule.startsWith("*.")) return host.endsWith(rule.slice(1)) && host !== rule.slice(2)
    return host === rule
  })
}

export type ImageDecision =
  | { status: "load"; src: string }
  | { status: "ask"; src: string; host: string }
  | { status: "blocked" }

export function decideImage(src: string | undefined, policy: FableImagePolicy = {}): ImageDecision {
  const url = safeImageUrl(src)
  if (!url) return { status: "blocked" }
  if (isHostAllowed(url.hostname, policy.allowedHosts)) return { status: "load", src: url.href }
  if (policy.otherHosts === "block") return { status: "blocked" }
  return { status: "ask", src: url.href, host: url.hostname }
}

const EXTENSIONS: Record<FableDownloadType, string> = {
  "text/plain": "txt",
  "text/markdown": "md",
  "text/csv": "csv",
  "application/json": "json",
  "text/calendar": "ics",
}

export function inferDownloadType(filename: string): FableDownloadType {
  const ext = filename.split(".").pop()?.toLowerCase()
  const match = (Object.entries(EXTENSIONS) as [FableDownloadType, string][]).find(([, e]) => e === ext)
  return match?.[0] ?? "text/plain"
}

/**
 * Strips path separators and control characters, and forces an extension
 * that matches the (allowlisted) MIME type so a file can never arrive as
 * `.html`, `.svg`, `.exe` or similar.
 */
export function safeFilename(filename: string, mimeType?: FableDownloadType) {
  const type = mimeType ?? inferDownloadType(filename)
  const ext = EXTENSIONS[type]
  const base =
    filename
      .replace(/[\u0000-\u001f\u007f<>:"/\\|?*]+/g, "-")
      .replace(/\.{2,}/g, "")
      .replace(/^[.-]+/, "")
      .replace(/\.[A-Za-z0-9]{1,8}$/, "")
      .trim()
      .slice(0, 80) || "download"
  return { filename: `${base}.${ext}`, mimeType: type }
}

/** Saves model-written text as a file in the browser. */
export function downloadText(filename: string, content: string, mimeType?: FableDownloadType) {
  const safe = safeFilename(filename, mimeType)
  const blob = new Blob([content], { type: `${safe.mimeType};charset=utf-8` })
  const href = URL.createObjectURL(blob)
  const anchor = document.createElement("a")
  anchor.href = href
  anchor.download = safe.filename
  anchor.rel = "noopener"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  setTimeout(() => URL.revokeObjectURL(href), 1000)
  return safe.filename
}

/** Neutralizes spreadsheet formula injection in CSV cells. */
export function toCsv(columns: { key: string; label: string }[], rows: Record<string, unknown>[]) {
  const cell = (value: unknown) => {
    let text = value === null || value === undefined ? "" : String(value)
    if (/^[=+\-@\t\r]/.test(text)) text = `'${text}`
    return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text
  }
  return [
    columns.map((column) => cell(column.label)).join(","),
    ...rows.map((row) => columns.map((column) => cell(row[column.key])).join(",")),
  ].join("\n")
}

export function hostLabel(url: string) {
  const parsed = parseUrl(url)
  return parsed ? parsed.hostname.replace(/^www\./, "") : url
}

export type FableNumberFormat = "number" | "currency" | "percent" | "compact"

export interface FormatOptions {
  format?: FableNumberFormat
  currency?: string
  locale?: string
}

/** Server and client must agree, so the default is fixed. Pass `locale` to FableProvider to change it. */
export const DEFAULT_LOCALE = "en-US"

const cache = new Map<string, Intl.NumberFormat>()

function numberFormat(locale: string | undefined = DEFAULT_LOCALE, options: Intl.NumberFormatOptions) {
  const key = `${locale ?? ""}|${JSON.stringify(options)}`
  let formatter = cache.get(key)
  if (!formatter) {
    try {
      formatter = new Intl.NumberFormat(locale, options)
    } catch {
      formatter = new Intl.NumberFormat(DEFAULT_LOCALE, options)
    }
    cache.set(key, formatter)
  }
  return formatter
}

/**
 * Percent values are written as percentages (12.5 means 12.5%), which is
 * what models produce naturally.
 */
export function formatNumber(value: number, { format = "number", currency, locale }: FormatOptions = {}) {
  if (!Number.isFinite(value)) return "—"
  switch (format) {
    case "currency":
      return numberFormat(locale, {
        style: "currency",
        currency: currency ?? "USD",
        maximumFractionDigits: Math.abs(value) >= 1000 ? 0 : 2,
      }).format(value)
    case "percent":
      return numberFormat(locale, { style: "percent", maximumFractionDigits: 1 }).format(value / 100)
    case "compact":
      return numberFormat(locale, { notation: "compact", maximumFractionDigits: 1 }).format(value)
    default:
      return numberFormat(locale, { maximumFractionDigits: 2 }).format(value)
  }
}

export function formatValue(value: unknown, options: FormatOptions = {}) {
  if (typeof value === "number") return formatNumber(value, options)
  if (value === null || value === undefined || value === "") return "—"
  if (typeof value === "boolean") return value ? "Yes" : "No"
  return String(value)
}

export function formatDate(value: unknown, locale?: string) {
  if (typeof value !== "string" && typeof value !== "number") return formatValue(value)
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return String(value)
  const dateOnly = typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value)
  return new Intl.DateTimeFormat(locale ?? DEFAULT_LOCALE, {
    dateStyle: "medium",
    timeZone: dateOnly ? "UTC" : undefined,
  }).format(date)
}

export function formatDelta(delta: number, locale?: string) {
  const sign = delta > 0 ? "+" : delta < 0 ? "−" : ""
  return `${sign}${numberFormat(locale, { maximumFractionDigits: 1 }).format(Math.abs(delta))}%`
}

import { z } from "zod"

import {
  ContentBlockSchema,
  LAYOUT_BLOCKS,
  STREAMABLE_BLOCKS,
  type ContentBlock,
  type FableBlockType,
} from "./schema"

/**
 * Turns a possibly-partial spec (from a streaming tool call) into a tree the
 * renderer can draw without guessing:
 *
 * - closed blocks are validated on their own; a bad block never takes the
 *   rest of the answer down with it;
 * - the one open block streams its content when that is meaningful, or
 *   becomes a skeleton that reserves its footprint;
 * - keys are positional, so local state survives every new chunk.
 */

export type Resolved =
  | { kind: "content"; key: string; block: ContentBlock; open: boolean }
  | { kind: "pending"; key: string; type?: string }
  | { kind: "invalid"; key: string; type?: string; issue: string }
  | {
      kind: "columns"
      key: string
      ratio: "equal" | "wide-left" | "wide-right"
      columns: Resolved[][]
    }
  | {
      kind: "section"
      key: string
      title?: string
      description?: string
      variant: "plain" | "card" | "muted"
      children: Resolved[]
    }
  | { kind: "tabs"; key: string; tabs: { label: string; children: Resolved[] }[] }

export interface ResolvedSpec {
  title?: string
  items: Resolved[]
  /** Blocks dropped because they failed validation. */
  invalidCount: number
}

const MAX_TOP_LEVEL = 24
const MAX_CHILDREN = 12

const str = (max: number) =>
  z
    .string()
    .transform((value) => value.slice(0, max))
    .optional()
    .catch(undefined)

const sectionHeader = z.object({
  title: str(120),
  description: str(300),
  variant: z.enum(["plain", "card", "muted"]).optional().catch(undefined),
})

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

/** Removes the trailing, most deeply nested array element (the one still being written). */
export function dropOpenTail(value: unknown): unknown {
  if (Array.isArray(value)) {
    if (value.length === 0) return undefined
    const last = value[value.length - 1]
    const trimmed = typeof last === "object" && last !== null ? dropOpenTail(last) : undefined
    return trimmed === undefined ? value.slice(0, -1) : [...value.slice(0, -1), trimmed]
  }
  if (isRecord(value)) {
    const keys = Object.keys(value)
    for (let index = keys.length - 1; index >= 0; index--) {
      const child = value[keys[index]]
      if (typeof child === "object" && child !== null) {
        const trimmed = dropOpenTail(child)
        if (trimmed !== undefined) return { ...value, [keys[index]]: trimmed }
      }
    }
  }
  return undefined
}

/**
 * Trims strings and arrays that are over their limit, which is the most
 * common way a good block fails (a button label a few characters too long).
 * Returns null when nothing could be repaired.
 */
function trimOversized(raw: unknown, issues: z.core.$ZodIssue[]): unknown {
  const fixable = issues.filter((issue) => issue.code === "too_big" && typeof issue.maximum === "number")
  if (!fixable.length || fixable.length !== issues.length) return null
  const copy = structuredClone(raw)
  for (const issue of fixable) {
    const parentPath = issue.path.slice(0, -1)
    const last = issue.path[issue.path.length - 1]
    let parent: unknown = copy
    for (const segment of parentPath) parent = (parent as Record<PropertyKey, unknown>)?.[segment as PropertyKey]
    if (!parent || typeof parent !== "object" || last === undefined) return null
    const record = parent as Record<PropertyKey, unknown>
    const value = record[last as PropertyKey]
    const max = Number((issue as { maximum: number | bigint }).maximum)
    if (typeof value === "string") record[last as PropertyKey] = `${value.slice(0, Math.max(0, max - 1)).trimEnd()}…`.slice(0, max)
    else if (Array.isArray(value)) record[last as PropertyKey] = value.slice(0, max)
    else return null
  }
  return copy
}

function parseContent(raw: unknown) {
  let parsed = ContentBlockSchema.safeParse(raw)
  for (let attempt = 0; attempt < 2 && !parsed.success; attempt++) {
    const repaired = trimOversized(raw, parsed.error.issues)
    if (repaired === null) break
    raw = repaired
    parsed = ContentBlockSchema.safeParse(raw)
  }
  return parsed
}

function parseOpen(raw: unknown) {
  let candidate: unknown = raw
  for (let attempt = 0; attempt < 4 && candidate !== undefined; attempt++) {
    const parsed = parseContent(candidate)
    if (parsed.success) return parsed.data
    candidate = dropOpenTail(candidate)
  }
  return null
}

function typeOf(raw: unknown): string | undefined {
  return isRecord(raw) && typeof raw.type === "string" ? raw.type : undefined
}

function resolveContent(raw: unknown, key: string, open: boolean): Resolved {
  const type = typeOf(raw)

  if (open) {
    if (!type || !STREAMABLE_BLOCKS.has(type as FableBlockType)) return { kind: "pending", key, type }
    const block = parseOpen(raw)
    return block ? { kind: "content", key, block, open: true } : { kind: "pending", key, type }
  }

  const parsed = parseContent(raw)
  if (parsed.success) return { kind: "content", key, block: parsed.data, open: false }
  const issue = parsed.error.issues[0]
  return {
    kind: "invalid",
    key,
    type,
    issue: issue ? `${issue.path.join(".") || "block"}: ${issue.message}` : "invalid block",
  }
}

function resolveChildren(raw: unknown, key: string, open: boolean): Resolved[] {
  if (!Array.isArray(raw)) return open ? [{ kind: "pending", key: `${key}.0` }] : []
  const list = raw.slice(0, MAX_CHILDREN)
  return list.map((child, index) =>
    resolveContent(child, `${key}.${index}`, open && index === list.length - 1)
  )
}

function resolveBlock(raw: unknown, key: string, open: boolean): Resolved {
  const type = typeOf(raw)
  if (!type || !LAYOUT_BLOCKS.has(type as FableBlockType) || !isRecord(raw)) {
    return resolveContent(raw, key, open)
  }

  if (type === "columns") {
    const columns = Array.isArray(raw.columns) ? raw.columns.slice(0, 3) : []
    const ratio = raw.ratio === "wide-left" || raw.ratio === "wide-right" ? raw.ratio : "equal"
    if (columns.length === 0) {
      return open ? { kind: "pending", key, type } : { kind: "invalid", key, type, issue: "columns: empty" }
    }
    return {
      kind: "columns",
      key,
      ratio,
      columns: columns.map((column, index) =>
        resolveChildren(
          isRecord(column) ? column.blocks : undefined,
          `${key}.${index}`,
          open && index === columns.length - 1
        )
      ),
    }
  }

  if (type === "section") {
    const header = sectionHeader.parse(raw)
    return {
      kind: "section",
      key,
      title: header.title,
      description: header.description,
      variant: header.variant ?? "plain",
      children: resolveChildren(raw.blocks, key, open),
    }
  }

  const tabs = Array.isArray(raw.tabs) ? raw.tabs.slice(0, 6) : []
  const usable = tabs
    .map((tab, index) => ({ tab, index }))
    .filter(({ tab }) => isRecord(tab) && typeof tab.label === "string" && tab.label.length > 0)
  if (usable.length === 0) {
    return open ? { kind: "pending", key, type } : { kind: "invalid", key, type, issue: "tabs: empty" }
  }
  return {
    kind: "tabs",
    key,
    tabs: usable.map(({ tab, index }) => {
      const record = tab as Record<string, unknown>
      return {
        label: String(record.label).slice(0, 40),
        children: resolveChildren(record.blocks, `${key}.${index}`, open && index === tabs.length - 1),
      }
    }),
  }
}

/** Every skipped block with its position, e.g. "block 2.1 (table): rows: Required". */
export function listIssues(items: Resolved[]): string[] {
  return items.flatMap((item) => {
    if (item.kind === "invalid") return [`block ${item.key} (${item.type ?? "unknown"}): ${item.issue}`]
    if (item.kind === "columns") return item.columns.flatMap(listIssues)
    if (item.kind === "section") return listIssues(item.children)
    if (item.kind === "tabs") return item.tabs.flatMap((tab) => listIssues(tab.children))
    return []
  })
}

function countInvalid(items: Resolved[]): number {
  return items.reduce((total, item) => {
    if (item.kind === "invalid") return total + 1
    if (item.kind === "columns") return total + item.columns.reduce((sum, column) => sum + countInvalid(column), 0)
    if (item.kind === "section") return total + countInvalid(item.children)
    if (item.kind === "tabs") return total + item.tabs.reduce((sum, tab) => sum + countInvalid(tab.children), 0)
    return total
  }, 0)
}

export function resolveSpec(input: unknown, streaming = false): ResolvedSpec {
  const spec = isRecord(input) ? input : {}
  const blocks = Array.isArray(spec.blocks) ? spec.blocks.slice(0, MAX_TOP_LEVEL) : []
  const items = blocks.map((block, index) =>
    resolveBlock(block, String(index), streaming && index === blocks.length - 1)
  )
  if (streaming && items.length === 0) items.push({ kind: "pending", key: "0" })
  return {
    title: typeof spec.title === "string" ? spec.title.slice(0, 120) : undefined,
    items,
    invalidCount: countInvalid(items),
  }
}

import { formatValue } from "./format"
import { FableSpecSchema, type ContentBlock, type FableBlock, type FableSpec } from "./schema"

/**
 * Deterministic Markdown for any spec: used for "copy response", exports,
 * emails, and clients that cannot render Fable blocks.
 */

const escapeCell = (value: unknown) => formatValue(value).replace(/\|/g, "\\|").replace(/\n/g, " ")

function content(block: ContentBlock): string {
  switch (block.type) {
    case "markdown":
      return block.text
    case "heading":
      return [
        block.eyebrow ? `_${block.eyebrow}_` : "",
        `${"#".repeat(block.level ?? 2)} ${block.text}`,
        block.description ?? "",
      ]
        .filter(Boolean)
        .join("\n\n")
    case "callout":
      return `> **${block.title ?? block.tone.toUpperCase()}**\n> ${block.text.replace(/\n/g, "\n> ")}`
    case "metrics":
      return block.items
        .map((item) => {
          const value = typeof item.value === "number" ? formatValue(item.value, { format: item.format, currency: item.currency }) : item.value
          const delta = item.delta !== undefined ? ` (${item.delta > 0 ? "+" : ""}${item.delta}%${item.deltaLabel ? ` ${item.deltaLabel}` : ""})` : ""
          return `- **${item.label}:** ${value}${delta}`
        })
        .join("\n")
    case "table": {
      const head = `| ${block.columns.map((column) => escapeCell(column.label)).join(" | ")} |`
      const rule = `| ${block.columns.map(() => "---").join(" | ")} |`
      const cell = (column: (typeof block.columns)[number], value: unknown) =>
        escapeCell(
          typeof value === "number" && (column.type === "currency" || column.type === "percent")
            ? formatValue(value, { format: column.type, currency: column.currency })
            : value
        )
      const rows = block.rows.map((row) => `| ${block.columns.map((column) => cell(column, row[column.key])).join(" | ")} |`)
      return [block.title ? `**${block.title}**` : "", [head, rule, ...rows].join("\n")].filter(Boolean).join("\n\n")
    }
    case "chart": {
      const head = `| ${[block.xKey, ...block.series.map((series) => series.label)].join(" | ")} |`
      const rule = `| ${[block.xKey, ...block.series].map(() => "---").join(" | ")} |`
      const rows = block.data.map((row) => `| ${[block.xKey, ...block.series.map((series) => series.key)].map((key) => escapeCell(row[key])).join(" | ")} |`)
      return [`**${block.title ?? "Chart"}**`, [head, rule, ...rows].join("\n")].join("\n\n")
    }
    case "details":
      return [block.title ? `**${block.title}**` : "", block.items.map((item) => `- **${item.label}:** ${item.value}`).join("\n")]
        .filter(Boolean)
        .join("\n\n")
    case "list": {
      const marker = (index: number) =>
        block.style === "numbered" || block.style === "steps" ? `${index + 1}.` : block.style === "check" ? "- [x]" : "-"
      return [
        block.title ? `**${block.title}**` : "",
        block.items
          .map((item, index) => `${marker(index)} ${item.meta && block.style === "timeline" ? `${item.meta} — ` : ""}**${item.title}**${item.description ? ` — ${item.description}` : ""}`)
          .join("\n"),
      ]
        .filter(Boolean)
        .join("\n\n")
    }
    case "checklist":
      return [block.title ? `**${block.title}**` : "", block.items.map((item) => `- [${item.checked ? "x" : " "}] ${item.label}`).join("\n")]
        .filter(Boolean)
        .join("\n\n")
    case "code":
      return `\`\`\`${block.language ?? ""}\n${block.code}\n\`\`\``
    case "quote":
      return `> ${block.text}${block.author ? `\n>\n> — ${block.author}${block.source ? `, ${block.source}` : ""}` : ""}`
    case "image":
      return `[Image: ${block.image.alt}](${block.image.src})`
    case "gallery":
      return block.images.map((image) => `- [Image: ${image.alt}](${image.src})`).join("\n")
    case "cards":
      return block.items.map((item) => `- **${item.title}**${item.description ? ` — ${item.description}` : ""}`).join("\n")
    case "hero":
      return [block.eyebrow ? `_${block.eyebrow}_` : "", `## ${block.title}`, block.description ?? ""].filter(Boolean).join("\n\n")
    case "article":
      return [
        `# ${block.title}`,
        block.subtitle ?? "",
        ...block.sections.map((section) => [section.heading ? `## ${section.heading}` : "", section.body].filter(Boolean).join("\n\n")),
      ]
        .filter(Boolean)
        .join("\n\n")
    case "form":
      return [block.title ? `**${block.title}**` : "", block.fields.map((field) => `- ${field.label}${field.required ? " (required)" : ""}`).join("\n")]
        .filter(Boolean)
        .join("\n\n")
    case "template":
      return block.body
    case "email":
      return [`**To:** ${(block.to ?? []).join(", ")}`, `**Subject:** ${block.subject}`, "", block.body].join("\n")
    case "actions":
      return block.items.map((action) => `- ${action.label}`).join("\n")
    case "file":
      return `📄 ${block.filename}${block.description ? ` — ${block.description}` : ""}`
    case "sources":
      return block.items.map((item, index) => `${index + 1}. [${item.title}](${item.url})`).join("\n")
    case "faq":
      return block.items.map((item) => `**${item.question}**\n\n${item.answer}`).join("\n\n")
    case "divider":
      return "---"
  }
}

function block(item: FableBlock): string {
  if (item.type === "columns") return item.columns.map((column) => column.blocks.map(content).join("\n\n")).join("\n\n")
  if (item.type === "section") return [item.title ? `### ${item.title}` : "", ...item.blocks.map(content)].filter(Boolean).join("\n\n")
  if (item.type === "tabs") return item.tabs.map((tab) => [`### ${tab.label}`, ...tab.blocks.map(content)].join("\n\n")).join("\n\n")
  return content(item)
}

export function specToMarkdown(input: FableSpec | unknown): string {
  const parsed = FableSpecSchema.safeParse(input)
  if (!parsed.success) return ""
  return parsed.data.blocks.map(block).filter(Boolean).join("\n\n")
}

"use client"

import * as React from "react"

import type { FableImagePolicy } from "./safety"

type Scalar = string | number | boolean | null

export interface FableHostAction {
  /** Shown in the confirmation step, e.g. "Send this email to 3 people?" */
  confirm?: string
  /** Runs the side effect. Throw to show an error; return a string to show a success note. */
  run: (payload: Record<string, Scalar>) => Promise<string | void> | string | void
}

export interface FableConfig {
  /** Sends a message as the user. Powers `reply` actions and form submits. */
  onReply?: (message: string) => void
  /** Side effects your app allows the model to request by name. */
  actions?: Record<string, FableHostAction>
  images?: FableImagePolicy
  locale?: string
  /** Disables every interactive control, e.g. while a response is streaming. */
  readOnly?: boolean
}

interface FableContextValue extends FableConfig {
  store: Map<string, unknown>
}

const FableContext = React.createContext<FableContextValue>({ store: new Map() })
const ScopeContext = React.createContext("fable")

export function FableProvider({ children, ...config }: FableConfig & { children: React.ReactNode }) {
  const [store] = React.useState(() => new Map<string, unknown>())
  const { onReply, actions, images, locale, readOnly } = config
  const value = React.useMemo(
    () => ({ onReply, actions, images, locale, readOnly, store }),
    [onReply, actions, images, locale, readOnly, store]
  )
  return <FableContext.Provider value={value}>{children}</FableContext.Provider>
}

/** Scopes widget state to one response (usually the tool call id). */
export function FableScope({ id, children }: { id: string; children: React.ReactNode }) {
  return <ScopeContext.Provider value={id}>{children}</ScopeContext.Provider>
}

export function useFable() {
  return React.useContext(FableContext)
}

/**
 * Like useState, but the value outlives remounts (tab switches, list
 * virtualization, re-renders of a streaming message) for this provider.
 */
export function useFableState<T>(key: string, initial: T | (() => T)) {
  const { store } = useFable()
  const scope = React.useContext(ScopeContext)
  const fullKey = `${scope}:${key}`
  const [value, setValue] = React.useState<T>(() =>
    store.has(fullKey) ? (store.get(fullKey) as T) : typeof initial === "function" ? (initial as () => T)() : initial
  )
  const update = React.useCallback(
    (next: React.SetStateAction<T>) => {
      setValue((current) => {
        const resolved = typeof next === "function" ? (next as (value: T) => T)(current) : next
        store.set(fullKey, resolved)
        return resolved
      })
    },
    [store, fullKey]
  )
  return [value, update] as const
}

