export function ChartBlock({ block }: { block: BlockOf<"chart"> }) {
  const { locale } = useFable()
  const [asTable, setAsTable] = useFableState("table", false)
  const format: FormatOptions = { format: block.format, currency: block.currency, locale }
  const compact: FormatOptions = { ...format, format: block.format === "percent" ? "percent" : "compact" }
  const gradientId = React.useId().replace(/:/g, "")

  const config = Object.fromEntries(
    block.series.map((series, index) => [series.key, { label: series.label, color: `var(--chart-${(index % 5) + 1})` }])
  ) satisfies ChartConfig

  const circular = block.kind === "pie" || block.kind === "donut"
  const pieSeries = block.series[0]
  const pieData = circular
    ? block.data
        .map((row, index) => ({
          __label: String(row[block.xKey] ?? ""),
          value: typeof row[pieSeries.key] === "number" ? (row[pieSeries.key] as number) : 0,
          fill: `var(--chart-${(index % 5) + 1})`,
        }))
        .filter((entry) => entry.value > 0)
    : []
  const pieTotal = pieData.reduce((sum, entry) => sum + entry.value, 0)

  const axis = {
    tickLine: false,
    axisLine: false,
    tickMargin: 8,
    tick: { fontSize: 12 },
  } as const

  const cartesian = (
    <>
      <CartesianGrid vertical={Boolean(block.horizontal)} horizontal={!block.horizontal} strokeDasharray="3 3" className="stroke-border" />
      {block.horizontal ? (
        <>
          <YAxis dataKey={block.xKey} type="category" width={96} {...axis} />
          <XAxis type="number" {...axis} tickFormatter={(value: number) => formatNumber(value, compact)} />
        </>
      ) : (
        <>
          <XAxis dataKey={block.xKey} {...axis} interval="preserveStartEnd" minTickGap={16} />
          <YAxis {...axis} width={48} tickFormatter={(value: number) => formatNumber(value, compact)} />
        </>
      )}
      <ChartTooltip cursor={{ className: "fill-muted/60 stroke-border" }} content={<ChartTip config={config} format={format} />} />
    </>
  )

  let chart: React.ReactElement
  if (circular) {
    chart = (
      <PieChart>
        <ChartTooltip content={<ChartTip config={{ value: { label: pieSeries.label } }} format={format} />} />
        <Pie
          data={pieData}
          dataKey="value"
          nameKey="__label"
          innerRadius={block.kind === "donut" ? "58%" : 0}
          outerRadius="92%"
          paddingAngle={block.kind === "donut" ? 2 : 0}
          strokeWidth={block.kind === "donut" ? 0 : 2}
          className="stroke-card"
          isAnimationActive={false}
        >
          {pieData.map((entry) => (
            <Cell key={entry.__label} fill={entry.fill} />
          ))}
        </Pie>
      </PieChart>
    )
  } else if (block.kind === "line") {
    chart = (
      <LineChart data={block.data} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
        {cartesian}
        {block.series.map((series, index) => (
          <Line
            key={series.key}
            dataKey={series.key}
            type="monotone"
            stroke={seriesColor(index)}
            strokeWidth={2}
            dot={block.data.length <= 12 ? { r: 2.5, strokeWidth: 0, fill: seriesColor(index) } : false}
            activeDot={{ r: 4, strokeWidth: 2, className: "stroke-card" }}
            isAnimationActive={false}
          />
        ))}
      </LineChart>
    )
  } else if (block.kind === "area") {
    chart = (
      <AreaChart data={block.data} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
        <defs>
          {block.series.map((series, index) => (
            <linearGradient key={series.key} id={`${gradientId}-${index}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={seriesColor(index)} stopOpacity={0.35} />
              <stop offset="100%" stopColor={seriesColor(index)} stopOpacity={0.02} />
            </linearGradient>
          ))}
        </defs>
        {cartesian}
        {block.series.map((series, index) => (
          <Area
            key={series.key}
            dataKey={series.key}
            type="monotone"
            stackId={block.stacked ? "stack" : undefined}
            stroke={seriesColor(index)}
            strokeWidth={2}
            fill={`url(#${gradientId}-${index})`}
            isAnimationActive={false}
          />
        ))}
      </AreaChart>
    )
  } else {
    chart = (
      <BarChart
        data={block.data}
        layout={block.horizontal ? "vertical" : "horizontal"}
        margin={{ top: 8, right: 8, left: 0, bottom: 0 }}
        barCategoryGap="22%"
      >
        {cartesian}
        {block.series.map((series, index) => (
          <Bar
            key={series.key}
            dataKey={series.key}
            stackId={block.stacked ? "stack" : undefined}
            fill={seriesColor(index)}
            radius={
              block.stacked && index < block.series.length - 1
                ? 0
                : block.horizontal
                  ? [0, 4, 4, 0]
                  : [4, 4, 0, 0]
            }
            maxBarSize={44}
            isAnimationActive={false}
          />
        ))}
      </BarChart>
    )
  }

  const height = block.horizontal ? Math.min(Math.max(block.data.length * 36 + 40, 180), 480) : 260

  return (
    <figure className={cn(surface, "p-4 @lg:p-5")}>
      <BlockHeader
        title={block.title}
        description={block.description}
        className="mb-4"
        actions={
          <IconAction label={asTable ? "Show chart" : "Show data table"} onClick={() => setAsTable((value) => !value)}>
            <SwapIcon swapped={asTable} from={TableIcon} to={ChartColumnIcon} />
          </IconAction>
        }
      />
      {asTable ? (
        <DataTable block={block} format={format} />
      ) : circular ? (
        <div className="grid items-center gap-6 @lg:grid-cols-[minmax(0,12rem)_1fr]">
          <ChartContainer config={config} className="mx-auto aspect-square w-full max-w-60">
            {chart}
          </ChartContainer>
          <ul className="space-y-2">
            {pieData.map((entry) => (
              <li key={entry.__label} className="flex items-center gap-2.5 text-sm">
                <span className="size-2.5 shrink-0 rounded-[3px]" style={{ background: entry.fill }} />
                <span className="min-w-0 flex-1 truncate">{entry.__label}</span>
                <span className="text-muted-foreground tabular-nums">{formatNumber(entry.value, format)}</span>
                <span className="w-12 text-end text-xs text-muted-foreground tabular-nums">
                  {pieTotal ? `${Math.round((entry.value / pieTotal) * 100)}%` : ""}
                </span>
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <>
          <ChartContainer config={config} className="aspect-auto w-full" style={{ height }}>
            {chart}
          </ChartContainer>
          {block.series.length > 1 ? (
            <ul className="mt-3 flex flex-wrap gap-x-4 gap-y-1.5">
              {block.series.map((series, index) => (
                <li key={series.key} className="flex items-center gap-1.5 text-xs text-muted-foreground">
                  <span className="size-2 rounded-[3px]" style={{ background: seriesColor(index) }} />
                  {series.label}
                </li>
              ))}
            </ul>
          ) : null}
        </>
      )}
      <figcaption className="sr-only">{block.title ?? `${block.kind} chart`}</figcaption>
    </figure>
  )
}

"use client"

import * as React from "react"
import { ChevronLeftIcon, ChevronRightIcon, ImageOffIcon, ShieldAlertIcon, XIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogTitle } from "@/components/ui/dialog"
import { cn } from "@/lib/utils"

import { useFable } from "../provider"
import { decideImage } from "../safety"
import type { BlockOf, FableImage } from "../schema"
import { BlockHeader, imageOutline } from "./shared"

const aspects = {
  auto: "",
  square: "aspect-square",
  landscape: "aspect-[4/3]",
  portrait: "aspect-[3/4]",
  wide: "aspect-[16/9]",
} as const

type Aspect = keyof typeof aspects

const approvedHosts = new Set<string>()

/**
 * Every model-provided image goes through here. Allowed hosts load lazily
 * with no referrer; other https hosts wait for the user; anything else
 * never loads.
 */
export function FableImg({
  image,
  aspect = "landscape",
  className,
  rounded = "rounded-lg",
  priority,
}: {
  image: FableImage
  aspect?: Aspect
  className?: string
  rounded?: string
  priority?: boolean
}) {
  const { images } = useFable()
  const decision = decideImage(image.src, images)
  const [approved, setApproved] = React.useState(() => decision.status === "ask" && approvedHosts.has(decision.host))
  const [state, setState] = React.useState<"loading" | "loaded" | "error">("loading")

  const frame = cn("relative overflow-hidden bg-muted", rounded, aspects[aspect], aspect === "auto" && "min-h-40", className)

  if (decision.status === "blocked" || state === "error") {
    return (
      <div className={cn(frame, "grid place-items-center")} role="img" aria-label={image.alt || "Image unavailable"}>
        <div className="flex flex-col items-center gap-1.5 px-4 text-center text-xs text-muted-foreground">
          <ImageOffIcon className="size-5 opacity-60" aria-hidden />
          <span className="line-clamp-2">{image.alt || "Image unavailable"}</span>
        </div>
      </div>
    )
  }

  if (decision.status === "ask" && !approved) {
    return (
      <div className={cn(frame, "grid place-items-center")}>
        <div className="flex max-w-60 flex-col items-center gap-2 px-4 text-center">
          <ShieldAlertIcon className="size-5 text-muted-foreground" aria-hidden />
          <p className="line-clamp-2 text-xs text-muted-foreground">
            {image.alt ? `“${image.alt}” from ` : "Image from "}
            <span className="font-medium text-foreground">{decision.host}</span>
          </p>
          <Button
            size="xs"
            variant="outline"
            onClick={(event) => {
              event.stopPropagation()
              approvedHosts.add(decision.host)
              setApproved(true)
            }}
          >
            Load image
          </Button>
        </div>
      </div>
    )
  }

  return (
    <div className={frame}>
      {state === "loading" ? <div className="absolute inset-0 animate-pulse bg-muted motion-reduce:animate-none" /> : null}
      {/* eslint-disable-next-line @next/next/no-img-element -- remote, policy-checked, model-provided URL */}
      <img
        src={decision.src}
        alt={image.alt}
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        referrerPolicy="no-referrer"
        onLoad={() => setState("loaded")}
        onError={() => setState("error")}
        className={cn(
          "size-full object-cover transition-opacity duration-500",
          aspect === "auto" && "h-auto",
          state === "loaded" ? "opacity-100" : "opacity-0"
        )}
      />
      <span aria-hidden className={cn("pointer-events-none absolute inset-0", rounded, imageOutline)} />
    </div>
  )
}

function Caption({ image }: { image: FableImage }) {
  if (!image.caption && !image.credit) return null
  return (
    <figcaption className="mt-2 flex flex-wrap items-baseline justify-between gap-x-3 gap-y-0.5 text-xs text-muted-foreground">
      {image.caption ? <span className="text-pretty">{image.caption}</span> : null}
      {image.credit ? <span className="opacity-80">{image.credit}</span> : null}
    </figcaption>
  )
}

export function ImageBlock({ block }: { block: BlockOf<"image"> }) {
  return (
    <figure>
      <FableImg image={block.image} aspect={block.aspect ?? "wide"} rounded="rounded-xl" />
      <Caption image={block.image} />
    </figure>
  )
}

function Lightbox({
  images,
  index,
  onIndex,
  onClose,
}: {
  images: FableImage[]
  index: number | null
  onIndex: (index: number) => void
  onClose: () => void
}) {
  const image = index === null ? null : images[index]
  const go = (step: number) => index !== null && onIndex((index + step + images.length) % images.length)
  return (
    <Dialog open={image !== null} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        showCloseButton={false}
        className="max-w-[min(64rem,calc(100vw-2rem))] gap-0 overflow-hidden bg-background p-0 @lg:max-w-[min(64rem,calc(100vw-2rem))]"
        onKeyDown={(event) => {
          if (event.key === "ArrowRight") go(1)
          if (event.key === "ArrowLeft") go(-1)
        }}
      >
        {image ? (
          <>
            <div className="relative bg-muted">
              <FableImg image={image} aspect="auto" rounded="rounded-none" className="max-h-[75vh] [&_img]:max-h-[75vh] [&_img]:object-contain" priority />
              <Button
                size="icon-sm"
                variant="secondary"
                className="absolute end-3 top-3 bg-background/80 backdrop-blur"
                onClick={onClose}
                aria-label="Close"
              >
                <XIcon />
              </Button>
              {images.length > 1 ? (
                <>
                  <Button
                    size="icon"
                    variant="secondary"
                    className="absolute start-3 top-1/2 -translate-y-1/2 bg-background/80 backdrop-blur rtl:rotate-180"
                    onClick={() => go(-1)}
                    aria-label="Previous image"
                  >
                    <ChevronLeftIcon />
                  </Button>
                  <Button
                    size="icon"
                    variant="secondary"
                    className="absolute end-3 top-1/2 -translate-y-1/2 bg-background/80 backdrop-blur rtl:rotate-180"
                    onClick={() => go(1)}
                    aria-label="Next image"
                  >
                    <ChevronRightIcon />
                  </Button>
                </>
              ) : null}
            </div>
            <div className="flex items-start justify-between gap-4 px-5 py-3.5">
              <div className="min-w-0">
                <DialogTitle className="text-sm font-medium">{image.caption ?? image.alt ?? "Image"}</DialogTitle>
                <DialogDescription className="text-xs">{image.credit ?? image.alt}</DialogDescription>
              </div>
              {images.length > 1 ? (
                <span className="shrink-0 text-xs text-muted-foreground tabular-nums">
                  {(index ?? 0) + 1} / {images.length}
                </span>
              ) : null}
            </div>
          </>
        ) : null}
      </DialogContent>
    </Dialog>
  )
}

function Tile({
  image,
  aspect,
  onOpen,
  className,
}: {
  image: FableImage
  aspect: Aspect
  onOpen: () => void
  className?: string
}) {
  return (
    <button
      type="button"
      onClick={onOpen}
      aria-label={`Open ${image.alt || "image"}`}
      className={cn(
        "group/tile relative block w-full overflow-hidden rounded-lg text-start outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        className
      )}
    >
      <FableImg
        image={image}
        aspect={aspect}
        className="h-full [&_img]:transition-[opacity,scale] [&_img]:duration-500 group-hover/tile:[&_img]:scale-[1.03]"
      />
      {image.caption ? (
        <span className="pointer-events-none absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/60 to-transparent px-3 pt-8 pb-2.5 text-xs font-medium text-white opacity-0 transition-opacity group-hover/tile:opacity-100 group-focus-visible/tile:opacity-100">
          {image.caption}
        </span>
      ) : null}
    </button>
  )
}

export function GalleryBlock({ block }: { block: BlockOf<"gallery"> }) {
  const [open, setOpen] = React.useState<number | null>(null)
  const images = block.images
  const scroller = React.useRef<HTMLDivElement>(null)

  let body: React.ReactNode
  if (block.layout === "featured" && images.length >= 3) {
    const [first, ...rest] = images
    const side = rest.slice(0, 4)
    const grid = side.length === 4
    body = (
      <div className="grid gap-2 @lg:grid-cols-[1.5fr_1fr]">
        <Tile image={first} aspect="landscape" onOpen={() => setOpen(0)} className="@lg:h-full @lg:[&>div]:aspect-auto @lg:[&>div]:h-full" />
        <div className={cn("grid gap-2", grid ? "grid-cols-2" : "grid-cols-2 @lg:grid-cols-1")}>
          {side.map((image, index) => (
            <Tile
              key={index}
              image={image}
              aspect={grid ? "square" : "landscape"}
              onOpen={() => setOpen(index + 1)}
              className={cn(!grid && side.length === 3 && index === 2 && "col-span-2 @lg:col-span-1")}
            />
          ))}
        </div>
      </div>
    )
  } else if (block.layout === "masonry") {
    const pattern: Aspect[] = ["portrait", "square", "landscape", "square", "portrait", "landscape"]
    body = (
      <div className="columns-2 gap-2 @lg:columns-3 [&>*]:mb-2">
        {images.map((image, index) => (
          <Tile key={index} image={image} aspect={pattern[index % pattern.length]} onOpen={() => setOpen(index)} className="break-inside-avoid" />
        ))}
      </div>
    )
  } else if (block.layout === "carousel") {
    const scrollBy = (direction: number) => {
      const node = scroller.current
      if (!node) return
      const rtl = getComputedStyle(node).direction === "rtl"
      node.scrollBy({ left: node.clientWidth * 0.8 * direction * (rtl ? -1 : 1), behavior: "smooth" })
    }
    body = (
      <div className="relative">
        <div
          ref={scroller}
          className="-mx-1 flex snap-x snap-mandatory gap-2 overflow-x-auto scroll-smooth px-1 pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
        >
          {images.map((image, index) => (
            <Tile key={index} image={image} aspect="portrait" onOpen={() => setOpen(index)} className="w-[62%] shrink-0 snap-start @lg:w-[38%]" />
          ))}
        </div>
        {images.length > 2 ? (
          <div className="mt-2 flex justify-end gap-1">
            <Button size="icon-sm" variant="outline" onClick={() => scrollBy(-1)} aria-label="Scroll back" className="rtl:rotate-180">
              <ChevronLeftIcon />
            </Button>
            <Button size="icon-sm" variant="outline" onClick={() => scrollBy(1)} aria-label="Scroll forward" className="rtl:rotate-180">
              <ChevronRightIcon />
            </Button>
          </div>
        ) : null}
      </div>
    )
  } else {
    const columns = images.length === 1 ? "grid-cols-1" : images.length === 2 || images.length === 4 ? "grid-cols-2" : "grid-cols-2 @lg:grid-cols-3"
    body = (
      <div className={cn("grid gap-2", columns)}>
        {images.map((image, index) => (
          <Tile key={index} image={image} aspect={images.length === 1 ? "wide" : "square"} onOpen={() => setOpen(index)} />
        ))}
      </div>
    )
  }

  return (
    <section aria-label={block.title ?? "Image gallery"} className="space-y-3">
      <BlockHeader title={block.title} />
      {body}
      <Lightbox images={images} index={open} onIndex={setOpen} onClose={() => setOpen(null)} />
    </section>
  )
}

"use client"

import { cn } from "@/lib/utils"

import type { BlockOf } from "../schema"
import { ActionButton } from "./actions"
import { FableImg } from "./media"
import { surface } from "./shared"

function Stats({ stats, inverted }: { stats: NonNullable<BlockOf<"hero">["stats"]>; inverted?: boolean }) {
  return (
    <dl className="flex flex-wrap gap-x-8 gap-y-3">
      {stats.map((stat, index) => (
        <div key={index} className="min-w-0">
          <dt className={cn("text-xs", inverted ? "text-white/70" : "text-muted-foreground")}>{stat.label}</dt>
          <dd className="font-heading text-xl font-semibold tracking-tight tabular-nums">{stat.value}</dd>
        </div>
      ))}
    </dl>
  )
}

function HeroActions({ block, stateKey }: { block: BlockOf<"hero">; stateKey: string }) {
  if (!block.actions?.length) return null
  return (
    <div className="flex flex-wrap gap-2">
      {block.actions.map((action, index) => (
        <ActionButton
          key={index}
          action={action}
          stateKey={`${stateKey}.a${index}`}
          size="lg"
          fallbackStyle={index === 0 ? "primary" : "outline"}
        />
      ))}
    </div>
  )
}

/**
 * Four compositions for an answer that deserves an opening:
 * split (text beside image), cover (text over image), editorial (type-led,
 * no image needed) and spotlight (centered on a quiet accent field).
 */
export function HeroBlock({ block, stateKey }: { block: BlockOf<"hero">; stateKey: string }) {
  const variant = block.variant === "cover" && !block.image ? "spotlight" : block.variant

  if (variant === "cover" && block.image) {
    return (
      <section className="relative isolate overflow-hidden rounded-2xl bg-neutral-950 text-white">
        <FableImg image={block.image} aspect="auto" rounded="rounded-none" className="absolute inset-0 -z-10 h-full min-h-0" priority />
        <div className="absolute inset-0 -z-10 bg-gradient-to-t from-black/85 via-black/45 to-black/10" />
        <div className="flex min-h-[22rem] flex-col justify-end gap-4 p-6 @lg:min-h-[26rem] @lg:p-8">
          {block.eyebrow ? (
            <p className="text-xs font-medium tracking-[0.12em] text-white/75 uppercase">{block.eyebrow}</p>
          ) : null}
          <h2 className="max-w-[20ch] font-heading text-3xl leading-[1.05] font-semibold tracking-tight text-balance @lg:text-[2.5rem]">
            {block.title}
          </h2>
          {block.description ? (
            <p className="max-w-[56ch] text-[0.9375rem] leading-relaxed text-pretty text-white/80">{block.description}</p>
          ) : null}
          {block.stats?.length ? <Stats stats={block.stats} inverted /> : null}
          <div className="[&_[data-variant=outline]]:border-white/30 [&_[data-variant=outline]]:bg-white/10 [&_[data-variant=outline]]:text-white [&_[data-variant=outline]]:backdrop-blur [&_[data-variant=outline]:hover]:bg-white/20">
            <HeroActions block={block} stateKey={stateKey} />
          </div>
        </div>
      </section>
    )
  }

  if (variant === "split") {
    return (
      <section className={cn(surface, "grid overflow-hidden @lg:grid-cols-2")}>
        <div className="flex flex-col justify-center gap-4 p-6 @lg:p-8">
          {block.eyebrow ? <p className="text-xs font-medium tracking-[0.12em] text-primary uppercase">{block.eyebrow}</p> : null}
          <h2 className="font-heading text-2xl leading-tight font-semibold tracking-tight text-balance @lg:text-3xl">{block.title}</h2>
          {block.description ? (
            <p className="text-[0.9375rem] leading-relaxed text-pretty text-muted-foreground">{block.description}</p>
          ) : null}
          {block.stats?.length ? <Stats stats={block.stats} /> : null}
          <HeroActions block={block} stateKey={stateKey} />
        </div>
        {block.image ? (
          <FableImg image={block.image} aspect="landscape" rounded="rounded-none" className="order-first h-full @lg:order-none @lg:aspect-auto" priority />
        ) : (
          <div aria-hidden className="order-first min-h-32 bg-[radial-gradient(120%_80%_at_100%_0%,color-mix(in_oklab,var(--primary)_22%,transparent),transparent_60%),radial-gradient(80%_60%_at_0%_100%,color-mix(in_oklab,var(--chart-2)_25%,transparent),transparent_70%)] @lg:order-none" />
        )}
      </section>
    )
  }

  if (variant === "editorial") {
    return (
      <section className="relative grid gap-6 border-y border-foreground/80 py-7 @lg:grid-cols-[1fr_auto] @lg:py-9">
        <div className="space-y-4">
          {block.eyebrow ? (
            <p className="flex items-center gap-2 text-xs font-medium tracking-[0.14em] text-muted-foreground uppercase">
              <span className="h-px w-6 bg-primary" aria-hidden />
              {block.eyebrow}
            </p>
          ) : null}
          <h2 className="max-w-[18ch] font-heading text-[2.25rem] leading-[1.02] font-semibold tracking-[-0.025em] text-balance @lg:text-5xl">
            {block.title}
          </h2>
          {block.description ? (
            <p className="max-w-[58ch] text-base leading-relaxed text-pretty text-muted-foreground">{block.description}</p>
          ) : null}
          <HeroActions block={block} stateKey={stateKey} />
        </div>
        {block.image ? (
          <FableImg image={block.image} aspect="portrait" className="w-full @lg:w-52" />
        ) : block.stats?.length ? (
          <dl className="grid content-end gap-4 @lg:min-w-40 @lg:border-s @lg:border-border @lg:ps-6">
            {block.stats.map((stat, index) => (
              <div key={index}>
                <dd className="font-heading text-3xl font-semibold tracking-tight tabular-nums">{stat.value}</dd>
                <dt className="text-xs text-muted-foreground">{stat.label}</dt>
              </div>
            ))}
          </dl>
        ) : null}
      </section>
    )
  }

  return (
    <section className="relative isolate overflow-hidden rounded-2xl bg-primary/[0.05] px-6 py-10 text-center ring-1 ring-primary/10 @lg:px-10 @lg:py-14">
      <div
        aria-hidden
        className="absolute inset-0 -z-10 bg-[radial-gradient(60%_80%_at_50%_0%,color-mix(in_oklab,var(--primary)_14%,transparent),transparent_70%)]"
      />
      <div className="mx-auto flex max-w-xl flex-col items-center gap-4">
        {block.image ? (
          <FableImg image={block.image} aspect="square" rounded="rounded-2xl" className="size-20 shadow-sm" />
        ) : null}
        {block.eyebrow ? <p className="text-xs font-medium tracking-[0.12em] text-primary uppercase">{block.eyebrow}</p> : null}
        <h2 className="font-heading text-3xl leading-tight font-semibold tracking-tight text-balance @lg:text-4xl">{block.title}</h2>
        {block.description ? (
          <p className="text-[0.9375rem] leading-relaxed text-pretty text-muted-foreground">{block.description}</p>
        ) : null}
        {block.stats?.length ? (
          <div className="flex justify-center">
            <Stats stats={block.stats} />
          </div>
        ) : null}
        <div className="flex justify-center">
          <HeroActions block={block} stateKey={stateKey} />
        </div>
      </div>
    </section>
  )
}

export function CardsBlock({ block, stateKey }: { block: BlockOf<"cards">; stateKey: string }) {
  const columns = block.columns ?? (block.items.length === 1 ? 1 : block.items.length % 3 === 0 ? 3 : 2)
  return (
    <section aria-label={block.title ?? "Cards"} className="space-y-3">
      {block.title ? <h3 className="font-heading text-[0.9375rem] font-semibold tracking-tight">{block.title}</h3> : null}
      <ul
        className={cn(
          "grid gap-3",
          columns === 2 && "@lg:grid-cols-2",
          columns === 3 && "@lg:grid-cols-2 @2xl:grid-cols-3"
        )}
      >
        {block.items.map((item, index) => (
          <li key={index} className={cn(surface, "group/card flex flex-col overflow-hidden", columns === 1 && item.image && "@lg:flex-row")}>
            {item.image ? (
              <div className={cn("p-1.5 pb-0", columns === 1 && "@lg:w-2/5 @lg:pe-0 @lg:pb-1.5")}>
                <FableImg image={item.image} aspect="landscape" className={cn(columns === 1 && "@lg:h-full @lg:aspect-auto")} />
              </div>
            ) : null}
            <div className="flex flex-1 flex-col gap-1.5 p-4">
              <div className="flex items-start justify-between gap-3">
                <h4 className="font-heading text-[0.9375rem] leading-snug font-semibold tracking-tight text-balance">{item.title}</h4>
                {item.badge ? (
                  <span className="shrink-0 rounded-full bg-primary/10 px-2 py-0.5 text-[0.6875rem] font-medium text-primary">
                    {item.badge}
                  </span>
                ) : null}
              </div>
              {item.meta ? <p className="text-xs text-muted-foreground tabular-nums">{item.meta}</p> : null}
              {item.description ? (
                <p className="text-sm leading-6 text-pretty text-muted-foreground">{item.description}</p>
              ) : null}
              {item.action ? (
                <div className="mt-auto pt-2">
                  <ActionButton action={item.action} stateKey={`${stateKey}.${index}`} size="sm" fallbackStyle="secondary" />
                </div>
              ) : null}
            </div>
          </li>
        ))}
      </ul>
    </section>
  )
}

"use client"

import * as React from "react"
import { CheckIcon, ClockIcon, FileTextIcon, GlobeIcon } from "lucide-react"

import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion"
import { Checkbox } from "@/components/ui/checkbox"
import { cn } from "@/lib/utils"

import { useFableState } from "../provider"
import { hostLabel, safeFilename, safeLinkUrl } from "../safety"
import type { BlockOf } from "../schema"
import { ActionButton } from "./actions"
import { FableImg } from "./media"
import { MemoProse } from "./prose"
import { BlockHeader, CopyAction, surface } from "./shared"

function slug(text: string, index: number) {
  return `${text.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "-").replace(/^-|-$/g, "").slice(0, 48) || "section"}-${index}`
}

/**
 * Long-form answer. Three or more headed sections get a table of contents,
 * the navigation aid long mixed-format replies usually lack.
 */
export function ArticleBlock({ block, stateKey, open }: { block: BlockOf<"article">; stateKey: string; open?: boolean }) {
  const prefix = React.useId().replace(/:/g, "")
  const headed = block.sections.filter((section) => section.heading)
  const toc = headed.length >= 3 && !open
  const markdown = [
    `# ${block.title}`,
    block.subtitle,
    ...block.sections.map((section) => [section.heading ? `## ${section.heading}` : "", section.body].filter(Boolean).join("\n\n")),
  ]
    .filter(Boolean)
    .join("\n\n")

  return (
    <article className="space-y-6">
      <header className="space-y-3">
        <h2 className="font-heading text-[1.75rem] leading-[1.1] font-semibold tracking-[-0.02em] text-balance @lg:text-[2.125rem]">
          {block.title}
        </h2>
        {block.subtitle ? (
          <p className="max-w-[60ch] text-[1.0625rem] leading-relaxed text-pretty text-muted-foreground">{block.subtitle}</p>
        ) : null}
        {block.byline || block.readingTime || !open ? (
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
            {block.byline ? <span className="font-medium text-foreground/80">{block.byline}</span> : null}
            {block.readingTime ? (
              <span className="inline-flex items-center gap-1">
                <ClockIcon className="size-3" aria-hidden />
                {block.readingTime}
              </span>
            ) : null}
            {!open ? (
              <span className="ms-auto flex items-center">
                <CopyAction text={markdown} label="Copy as Markdown" />
                <ActionButton
                  action={{
                    type: "download",
                    label: "Download",
                    filename: block.title,
                    mimeType: "text/markdown",
                    content: markdown,
                  }}
                  stateKey={`${stateKey}.dl`}
                  size="sm"
                  fallbackStyle="ghost"
                  className="text-muted-foreground"
                />
              </span>
            ) : null}
          </div>
        ) : null}
      </header>

      {block.cover ? (
        <figure>
          <FableImg image={block.cover} aspect="wide" rounded="rounded-xl" priority />
          {block.cover.caption ? <figcaption className="mt-2 text-xs text-muted-foreground">{block.cover.caption}</figcaption> : null}
        </figure>
      ) : null}

      <div className={cn(toc && "grid gap-8 @3xl:grid-cols-[minmax(0,1fr)_11rem]")}>
        <div className="min-w-0 space-y-7">
          {block.sections.map((section, index) => (
            <section key={index} aria-labelledby={section.heading ? `${prefix}-${slug(section.heading, index)}` : undefined} className="scroll-mt-20">
              {section.heading ? (
                <h3
                  id={`${prefix}-${slug(section.heading, index)}`}
                  className="mb-3 scroll-mt-20 font-heading text-lg font-semibold tracking-tight text-balance"
                >
                  {section.heading}
                </h3>
              ) : null}
              <MemoProse className="text-base [&_p]:leading-[1.75]">{section.body}</MemoProse>
            </section>
          ))}
        </div>
        {toc ? (
          <nav aria-label="On this article" className="order-first @3xl:order-none">
            <div className="@3xl:sticky @3xl:top-4">
              <p className="mb-2 text-xs font-medium tracking-[0.08em] text-muted-foreground uppercase">Contents</p>
              <ol className="flex gap-1 overflow-x-auto border-b border-border pb-2 text-sm @3xl:flex-col @3xl:border-b-0 @3xl:border-s @3xl:pb-0">
                {block.sections.map((section, index) =>
                  section.heading ? (
                    <li key={index} className="shrink-0">
                      <a
                        href={`#${prefix}-${slug(section.heading, index)}`}
                        className="block rounded-md px-2 py-1 text-muted-foreground transition-colors hover:text-foreground @3xl:-ms-px @3xl:rounded-none @3xl:border-s @3xl:border-transparent @3xl:px-3 @3xl:hover:border-foreground/40"
                      >
                        {section.heading}
                      </a>
                    </li>
                  ) : null
                )}
              </ol>
            </div>
          </nav>
        ) : null}
      </div>
    </article>
  )
}

export function ListBlock({ block }: { block: BlockOf<"list"> }) {
  const header = block.title ? <BlockHeader title={block.title} className="mb-3" /> : null

  if (block.style === "steps" || block.style === "timeline") {
    const timeline = block.style === "timeline"
    return (
      <section aria-label={block.title ?? (timeline ? "Timeline" : "Steps")}>
        {header}
        <ol className="relative">
          {block.items.map((item, index) => {
            const status = item.status ?? (timeline ? undefined : "upcoming")
            const last = index === block.items.length - 1
            return (
              <li key={index} className="relative grid grid-cols-[1.75rem_1fr] gap-x-3 pb-5 last:pb-0">
                {!last ? (
                  <span
                    aria-hidden
                    className={cn(
                      "absolute start-[0.8125rem] top-8 bottom-1 w-px",
                      status === "done" ? "bg-primary/40" : "bg-border"
                    )}
                  />
                ) : null}
                <span
                  aria-hidden
                  className={cn(
                    "relative z-[1] mt-0.5 grid size-7 place-items-center rounded-full text-xs font-semibold tabular-nums ring-1",
                    timeline && "mt-1.5 size-3.5 ms-[0.4375rem] rounded-full bg-background ring-2 ring-primary/60",
                    !timeline && status === "done" && "bg-primary text-primary-foreground ring-primary",
                    !timeline && status === "current" && "bg-background text-primary ring-2 ring-primary",
                    !timeline && status === "upcoming" && "bg-muted text-muted-foreground ring-border"
                  )}
                >
                  {timeline ? null : status === "done" ? <CheckIcon className="size-3.5" /> : index + 1}
                </span>
                <div className="min-w-0 space-y-0.5">
                  <div className="flex flex-wrap items-baseline gap-x-2">
                    {timeline && item.meta ? (
                      <span className="text-xs font-medium text-primary tabular-nums">{item.meta}</span>
                    ) : null}
                    <p className={cn("text-sm leading-7 font-semibold text-pretty", status === "upcoming" && !timeline && "text-foreground/80")}>
                      {item.title}
                    </p>
                    {!timeline && item.meta ? <span className="text-xs text-muted-foreground">{item.meta}</span> : null}
                    {status === "current" && !timeline ? <span className="sr-only">(current step)</span> : null}
                  </div>
                  {item.description ? (
                    <p className="text-sm leading-6 text-pretty text-muted-foreground">{item.description}</p>
                  ) : null}
                </div>
              </li>
            )
          })}
        </ol>
      </section>
    )
  }

  const Tag = block.style === "numbered" ? "ol" : "ul"
  return (
    <section aria-label={block.title ?? "List"}>
      {header}
      <Tag className="space-y-2.5">
        {block.items.map((item, index) => (
          <li key={index} className="flex gap-3">
            <span
              aria-hidden
              className={cn(
                "mt-[0.3rem] grid shrink-0 place-items-center",
                block.style === "bullet" && "mt-[0.6rem] size-1.5 rounded-full bg-foreground/40",
                block.style === "numbered" && "size-5 rounded-md bg-muted text-[0.6875rem] font-semibold text-muted-foreground tabular-nums",
                block.style === "check" && "size-5 rounded-full bg-primary/10 text-primary"
              )}
            >
              {block.style === "numbered" ? index + 1 : block.style === "check" ? <CheckIcon className="size-3" /> : null}
            </span>
            <div className="min-w-0">
              <p className="text-[0.9375rem] leading-7 text-pretty">
                <span className={cn(item.description && "font-medium")}>{item.title}</span>
                {item.meta ? <span className="ms-2 text-xs text-muted-foreground">{item.meta}</span> : null}
              </p>
              {item.description ? (
                <p className="text-sm leading-6 text-pretty text-muted-foreground">{item.description}</p>
              ) : null}
            </div>
          </li>
        ))}
      </Tag>
    </section>
  )
}

export function ChecklistBlock({ block }: { block: BlockOf<"checklist"> }) {
  const [checked, setChecked] = useFableState<boolean[]>("checked", () => block.items.map((item) => Boolean(item.checked)))
  const id = React.useId()
  const done = block.items.filter((_, index) => checked[index]).length
  const progress = block.items.length ? Math.round((done / block.items.length) * 100) : 0

  return (
    <section className={cn(surface, "p-4 @lg:p-5")} aria-label={block.title ?? "Checklist"}>
      <div className="mb-3 flex items-center justify-between gap-3">
        <h3 className="font-heading text-[0.9375rem] font-semibold tracking-tight">{block.title ?? "Checklist"}</h3>
        <span className="text-xs text-muted-foreground tabular-nums" aria-live="polite">
          {done} of {block.items.length} done
        </span>
      </div>
      <div
        className="mb-3 h-1 overflow-hidden rounded-full bg-muted"
        role="progressbar"
        aria-valuenow={progress}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label="Checklist progress"
      >
        <div className="h-full rounded-full bg-primary transition-[width] duration-500 ease-out" style={{ width: `${progress}%` }} />
      </div>
      <ul className="-mx-2">
        {block.items.map((item, index) => {
          const isChecked = Boolean(checked[index])
          return (
            <li key={index}>
              <label
                htmlFor={`${id}-${index}`}
                className="flex cursor-pointer items-start gap-3 rounded-lg px-2 py-2 transition-colors hover:bg-muted/50"
              >
                <Checkbox
                  id={`${id}-${index}`}
                  checked={isChecked}
                  onCheckedChange={(value) =>
                    setChecked((current) => {
                      const next = block.items.map((_, i) => Boolean(current[i]))
                      next[index] = value === true
                      return next
                    })
                  }
                  className="mt-0.5"
                />
                <span className="min-w-0 flex-1">
                  <span
                    className={cn(
                      "block text-sm leading-5 text-pretty transition-colors",
                      isChecked && "text-muted-foreground line-through decoration-foreground/30"
                    )}
                  >
                    {item.label}
                  </span>
                  {item.note ? <span className="mt-0.5 block text-xs text-muted-foreground">{item.note}</span> : null}
                </span>
              </label>
            </li>
          )
        })}
      </ul>
    </section>
  )
}

